const j = $input.first().json;
const reasons = [];
let quiet = false;
let disabled = false;
if (String(j.kill_switch).toLowerCase() !== 'true') { reasons.push('Automatic outreach disabled by administrator.'); disabled = true; }
const phtHour = Number(new Date().toLocaleString('en-US', { hour: 'numeric', hour12: false, timeZone: 'Asia/Manila' }));
if (reasons.length === 0 && phtHour < 7) { reasons.push('Before daily 7:00 AM PHT send window - skipping quietly.'); quiet = true; }
if (reasons.length === 0 && j.run_done === true) { reasons.push('Daily outreach run already completed today - skipping quietly.'); quiet = true; }
const proceed = reasons.length === 0;
const notify = !proceed && !quiet && !disabled;
return [{ json: { proceed, abort_reason: reasons.join(' '), quiet, disabled, notify, threshold: Number(j.threshold), cap: Number(j.cap) } }];

const cap = $json;
const cand = $('Daily Batch').item.json;
const withinCap = Number(cap.sent_so_far) < Number(cap.cap);
const enabled = String(cap.kill_switch).toLowerCase() === 'true';
const reason = !enabled ? 'Automatic outreach disabled by administrator.' : (!withinCap ? 'Daily cap reached.' : null);
return { json: { ...cand, sent_so_far: Number(cap.sent_so_far), cap: Number(cap.cap), threshold: Number(cap.threshold), kill_switch: cap.kill_switch, gate_ok: withinCap && enabled, gate_skip_reason: reason } };

const r = $json;
const reasons = [];
const emailOk = !!(r.email && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(r.email));
if (!emailOk) reasons.push('Invalid or missing email address.');
if (r.duplicate_of) reasons.push('Lead is marked as a duplicate.');
if (r.do_not_contact) reasons.push('Lead is marked Do Not Contact.');
if (r.excluded_from_outreach) reasons.push('Lead is manually excluded from outreach.');
if (r.qualification_score == null || Number(r.qualification_score) < Number(r.threshold)) reasons.push('Qualification score below threshold.');
if (!r.business_name) reasons.push('Missing required field: business_name.');
const hasWebsite = !!(r.website && /^https?:\/\//i.test(String(r.website)));
return { json: { ...r, basic_passed: reasons.length === 0, basic_reasons: reasons, has_website: hasWebsite } };

const httpItem = $json;
const cand = $('Validate Basic').item.json;
const failed = !!(httpItem.error);
const reasons = cand.basic_reasons.slice();
if (failed) reasons.push('Website is not reachable.');
return { json: { ...cand, website_ok: !failed, final_passed: cand.basic_passed && !failed, fail_reasons: reasons } };

const COMPANY = 'KQuality Cleaning Services';
const SEGMENT_PITCH = {
  commercial_office: 'we help Adelaide offices keep their workspaces spotless so staff and clients always walk into a fresh, professional space',
  real_estate_strata: 'we support property and strata managers with dependable common-area, end-of-lease and vacate cleans across their portfolios',
  medical_childcare_gym: 'we provide compliance-grade cleaning and sanitisation for medical, childcare and fitness spaces where hygiene standards are non-negotiable',
  builders_construction: 'we handle post-construction and handover cleans so your sites are presentation-ready on deadline',
  hospitality_venues: 'we keep hospitality venues guest-ready with thorough after-service and overnight cleans',
  education_training: 'we help schools and learning centres maintain clean, healthy spaces for students and staff',
  retail_showrooms: 'we keep showrooms and retail floors presentation-perfect so your stock always looks its best'
};
const DEFAULT_PITCH = 'we provide reliable commercial cleaning for Adelaide businesses';
const ROLE_OK = /^(Owner|Co-?Owner|Director|Managing Director|CEO|Founder|Co-?Founder|Principal)$/i;
const NAME_BLOCK = /(Care|Quality|Executive|Nurse|Registered|Enrolled|General|Office|Property|Practice|Team|Group|Services)/i;
const AU_TAIL_RE = /,\s*Australia\s*$/i;
const STATE_RE = /\s+(SA|NSW|VIC|QLD|WA|NT|TAS|ACT)\s+\d{4}.*$/i;
const suburbOf = (r) => { if (r.suburb) return r.suburb; const a = (r.address || '').replace(AU_TAIL_RE, ''); const p = a.split(','); return p.length < 2 ? '' : p[p.length - 1].replace(STATE_RE, '').trim(); };
const bandOf = (s) => s == null ? 'cold' : (Number(s) >= 80 ? 'hot' : (Number(s) >= 55 ? 'warm' : 'cold'));
const clean = (t) => String(t || '').replace(/\s+/g, ' ').trim();
const r = $json;
const profile = r.profile || {};
const band = bandOf(r.qualification_score);
const suburb = suburbOf(r);
const pitch = SEGMENT_PITCH[r.segment_code] || DEFAULT_PITCH;
const people = Array.isArray(profile.people) ? profile.people : [];
const person = people.find(p => p && ROLE_OK.test(String(p.role || '')) && /^[A-Z][a-z]{1,15} [A-Z][a-z]{1,20}$/.test(String(p.name || '')) && !NAME_BLOCK.test(String(p.name)));
const firstName = person ? person.name.split(' ')[0] : null;
const greeting = firstName ? ('Hi ' + firstName + ',') : ('Hi ' + clean(r.business_name) + ' team,');
let aboutLine = '';
const desc = clean(profile.description);
if (desc) {
  let snip = desc.slice(0, 110);
  if (desc.length > 110) { snip = snip.slice(0, snip.lastIndexOf(' ')) + '...'; }
  aboutLine = 'I came across ' + clean(r.business_name) + ' recently - "' + snip + '" - and it is exactly the kind of business we enjoy working with.';
} else {
  aboutLine = 'I came across ' + clean(r.business_name) + (suburb ? ' in ' + suburb : '') + ' recently and wanted to reach out directly.';
}
let ask = '';
if (band === 'hot') {
  ask = 'Would you have 10 minutes this week for a quick walkthrough? We can put together a no-obligation quote tailored to your space - no pressure either way.';
} else if (band === 'warm') {
  ask = 'If cleaning is on your radar this quarter, I would love to show you how we work with businesses like yours - happy to send more info or jump on a short call, whatever suits you best.';
} else {
  ask = 'If it is ever useful down the track, I am happy to send over a short summary of what we offer, just so we are on your radar when the timing is right.';
}
const subjectBase = suburb ? (clean(r.business_name) + ' - cleaning support in ' + suburb) : ('Cleaning support for ' + clean(r.business_name));
const fallback_subject = band === 'hot' ? subjectBase + ' (quick quote offer)' : subjectBase;
const fallback_body = greeting + '\n\n' + aboutLine + '\n\nWe are ' + COMPANY + ', a local Adelaide team - ' + pitch + '.\n\n' + ask + '\n\nKind regards,\n' + COMPANY + '\n\n(If this has reached the wrong person, I would appreciate being pointed to whoever looks after your premises.)';
const ai_summary = (r.enrichment && r.enrichment.ai && r.enrichment.ai.opportunities) ? JSON.stringify(r.enrichment.ai.opportunities).slice(0, 800) : null;
return { json: { ...r, fallback_subject, fallback_body, ai_request: {
  business: { name: clean(r.business_name), industry: r.segment_code || null, location: suburb || clean(r.address) || null, description: desc || null },
  sender: { name: 'Michelle', company: COMPANY },
  contact_name: firstName,
  notes: 'qualification band: ' + band + '. segment pitch: ' + pitch + '. Local Adelaide team.' + (ai_summary ? (' Known cleaning opportunities: ' + ai_summary) : '')
} } };

const prep = $('Prepare Daily Outreach').item.json;
const res = $json;
const ok = res && res.success === true && res.data && typeof res.data.email_body === 'string' && res.data.email_body.trim().length >= 60 && res.data.subject;
const subject = ok ? String(res.data.subject).slice(0, 150) : prep.fallback_subject;
const body = ok ? res.data.email_body.trim() : prep.fallback_body;
const out = { ...prep };
delete out.ai_request;
delete out.fallback_subject;
delete out.fallback_body;
out.subject = subject;
out.body = body;
out.method = ok ? ('ai_generate_outreach_' + res.prompt_version) : 'daily_auto_v1';
out.compose_valid = !!(subject && subject.trim() && body && body.trim() && prep.email);
return { json: out };
